insert into public.omnii_form_templates (id, version, lifecycle, form_type, name, description, subject_kind, schema, rules, workflow, authority, timing, cost_model, privacy, provenance) values
('transport_nab_vehicle_biography','1','active','registration','NAB Vehicle Biography Intake','Register a mobility asset from origin/manufacture through import and lifecycle evidence.','mobility_asset',jsonb_build_object('fields',jsonb_build_array('asset_identity','manufacturer','manufacture_date','seller','shipment','origin','importer','documents','ownership','initial_condition','energy_system','conversion_state','evidence')),'[{"rule":"identity_integrity","severity":"critical"},{"rule":"provenance_required","severity":"error"},{"rule":"authority_scope","severity":"critical"}]'::jsonb,'{"stages":["draft","submit","validate","provenance_review","inspection","approve","activate","audit"]}'::jsonb,'{"approval_gates":["nab-registry-authority"]}'::jsonb,'{"validation_hours":48,"review_days":10}'::jsonb,'{"type":"no_platform_fee"}'::jsonb,'{"classification":"controlled","minimize":"required"}'::jsonb,'{"source":"omnii-transport-certification","version":"1"}'::jsonb),
('transport_inspection','1','active','inspection','Transport Asset Inspection','Capture physical inspection, test results, evidence and approval for a transport asset or infrastructure node.','transport_asset',jsonb_build_object('fields',jsonb_build_array('subject','inspection_type','location','inspector','checks','measurements','images','findings','evidence','recommendation')),'[{"rule":"qualified_inspector","severity":"critical"},{"rule":"evidence_required","severity":"error"},{"rule":"conflict_check","severity":"error"}]'::jsonb,'{"stages":["request","schedule","assign","inspect","record","quality_review","approve_or_follow_up","close"]}'::jsonb,'{"approval_gates":["inspection-supervisor"]}'::jsonb,'{"schedule_hours":72,"review_hours":48}'::jsonb,'{"type":"contextual"}'::jsonb,'{"classification":"controlled"}'::jsonb,'{"source":"omnii-transport-certification","version":"1"}'::jsonb),
('transport_green_conversion','1','active','conversion','Green Mobility Conversion Request','Request and approve CNG, electric or other lawful green-energy conversion, including DIY guidance or booked professional installation.','mobility_asset',jsonb_build_object('fields',jsonb_build_array('asset','current_powertrain','target_system','kit','installer','diy_or_professional','site','queue','slot','estimated_cost','safety_documents','evidence')),'[{"rule":"compatibility","severity":"critical"},{"rule":"qualified_installer_or_diy_ack","severity":"error"},{"rule":"safety_evidence","severity":"critical"}]'::jsonb,'{"stages":["draft","submit","compatibility","quote","slot_or_diy","technical_review","approve","install","inspect","activate"]}'::jsonb,'{"approval_gates":["green-conversion-authority","inspection-supervisor"]}'::jsonb,'{"compatibility_hours":24,"technical_review_hours":48}'::jsonb,'{"type":"quote_plus_parts_and_service"}'::jsonb,'{"classification":"controlled"}'::jsonb,'{"source":"bridge-cngneers","version":"1"}'::jsonb),
('transport_energy_slot','1','active','booking','Energy Station Slot','Reserve a CNG, EV charging, battery swap or future energy service slot using live capacity and queue state.','energy_service',jsonb_build_object('fields',jsonb_build_array('station','energy_type','vehicle','arrival_window','service_duration','queue_position','capacity','price','requirements')),'[{"rule":"station_availability","severity":"error"},{"rule":"vehicle_compatibility","severity":"error"}]'::jsonb,'{"stages":["select","validate","reserve","confirm","arrive","service","complete","reconcile"]}'::jsonb,'{"approval_gates":[]}'::jsonb,'{"hold_minutes":15}'::jsonb,'{"type":"provider_defined"}'::jsonb,'{"classification":"operational"}'::jsonb,'{"source":"bridge-energy","version":"1"}'::jsonb),
('transport_fleet_onboarding','1','active','registration','Fleet Operator Onboarding','Register a fleet operator, assets, responsible personnel, operating scope and evidence for activation.','mobility_operator',jsonb_build_object('fields',jsonb_build_array('operator','organization','assets','drivers_or_crew','licenses','insurance','maintenance_plan','safety_plan','operating_area','evidence')),'[{"rule":"operator_identity","severity":"critical"},{"rule":"required_credentials","severity":"error"},{"rule":"safety_plan","severity":"error"}]'::jsonb,'{"stages":["draft","submit","validate","compliance_review","approve","activate","monitor","renew"]}'::jsonb,'{"approval_gates":["institutional-authority","compliance-clearance"]}'::jsonb,'{"validation_hours":48,"review_hours":120}'::jsonb,'{"type":"contextual"}'::jsonb,'{"classification":"controlled"}'::jsonb,'{"source":"fleet-omnii","version":"1"}'::jsonb),
('transport_technician_credential','1','active','credential','CNGNEERS Technical Credential','Apply for or renew a technical workforce credential for green mobility conversion, installation, maintenance or inspection.','person',jsonb_build_object('fields',jsonb_build_array('applicant','qualifications','training','experience','specializations','assessments','identity','evidence')),'[{"rule":"identity","severity":"critical"},{"rule":"qualification_evidence","severity":"error"},{"rule":"assessment_required","severity":"error"}]'::jsonb,'{"stages":["submit","validate","technical_review","assessment","approve","issue","renew_or_suspend"]}'::jsonb,'{"approval_gates":["technical-authority"]}'::jsonb,'{"review_hours":120}'::jsonb,'{"type":"training_or_assessment_fee"}'::jsonb,'{"classification":"controlled"}'::jsonb,'{"source":"cngneers","version":"1"}'::jsonb),
('transport_rental','1','active','booking','Vehicle / Mobility Rental','Rent a vehicle or mobility asset with verified biography, condition, eligibility, custody and return obligations.','mobility_asset',jsonb_build_object('fields',jsonb_build_array('renter','asset','purpose','start','end','pickup','requirements','insurance','deposit','terms','condition_before','condition_after')),'[{"rule":"asset_availability","severity":"error"},{"rule":"renter_eligibility","severity":"error"},{"rule":"condition_evidence","severity":"error"}]'::jsonb,'{"stages":["select","verify","reserve","contract","handover","in_use","return","inspect","reconcile","close"]}'::jsonb,'{"approval_gates":["rental-provider-policy"]}'::jsonb,'{"hold_minutes":15}'::jsonb,'{"type":"provider_defined"}'::jsonb,'{"classification":"operational"}'::jsonb,'{"source":"charter-rental","version":"1"}'::jsonb),
('transport_tokenization','1','active','tokenization','Transport Asset / Right Tokenization Request','Prepare an eligible transport asset, capacity, receivable or other right for lawful digital representation and regulated issuance review.','transport_right',jsonb_build_object('fields',jsonb_build_array('underlying_asset_or_right','verified_provenance','rights','obligations','issuer','jurisdiction','regulated_activity','custody','settlement','fractionalization','token_standard','legal_opinion','evidence')),'[{"rule":"verified_underlying","severity":"critical"},{"rule":"issuer_authorization","severity":"critical"},{"rule":"custody_and_settlement","severity":"critical"},{"rule":"legal_effect","severity":"critical"}]'::jsonb,'{"stages":["draft","eligibility","legal_review","authority_review","issuer_review","approve_or_reject","issue_if_authorized","monitor","suspend_or_revoke"]}'::jsonb,'{"approval_gates":["authorized-issuer","legal-review","regulated-custodian-when-required"]}'::jsonb,'{"legal_review_days":15,"authority_review_days":15}'::jsonb,'{"type":"regulated_contextual"}'::jsonb,'{"classification":"highly_controlled","privacy":"minimize"}'::jsonb,'{"source":"omnii-tokenization-boundary","version":"1"}'::jsonb)
insert into public.omnii_institutional_workflows (id,version,category,name,description,states,transitions,approval_gates,sla_rules,exception_rules,lifecycle,provenance) values
('transport:nab-biography','1.0.0','registration','NAB Vehicle Biography Lifecycle','Lifecycle for a vehicle or mobility asset from provenance intake through verified activation.',jsonb_build_array('draft','submitted','validated','provenance_review','inspection_due','in_review','approved','active','suspended','retired'),'{"draft":["submit"],"submitted":["validate","reject"],"validated":["provenance_review"],"provenance_review":["request_inspection","approve_provenance","reject"],"inspection_due":["complete_inspection","reject"],"in_review":["approve","reject","request_deficiency"],"approved":["activate"],"active":["suspend","retire"],"suspended":["reinstate","retire"]}'::jsonb,'["nab-registry-authority"]'::jsonb,'{"validation_hours":48,"review_days":10}'::jsonb,'["missing_evidence","duplicate_asset","authority_expired","conflict_of_interest"]'::jsonb,'active','{"source":"omnii-transport","version":"1"}'::jsonb),
('transport:conversion','1.0.0','conversion','Green Conversion Approval','CNG/EV and future green powertrain conversion workflow.',jsonb_build_array('submitted','compatibility_review','quoted','scheduled','technical_review','approved','installed','inspected','activated','rejected'),'{"submitted":["check_compatibility","reject"],"compatibility_review":["quote","reject"],"quoted":["reserve_slot","accept"],"scheduled":["technical_review","cancel"],"technical_review":["approve","request_change","reject"],"approved":["install"],"installed":["inspection"],"inspected":["activate","rework"]}'::jsonb,'["green-conversion-authority","inspection-supervisor"]'::jsonb,'{"compatibility_hours":24,"technical_review_hours":48}'::jsonb,'["incompatible_asset","unsafe_installation","missing_kit","evidence_gap"]'::jsonb,'active','{"source":"bridge-cngneers","version":"1"}'::jsonb),
('transport:tokenization','1.0.0','tokenization','Transport Tokenization Approval','Controlled lifecycle for digital representation of transport assets or rights.',jsonb_build_array('draft','eligible','legal_review','authority_review','issuer_review','approved','issued','suspended','revoked','rejected'),'{"draft":["assess_eligibility"],"eligible":["legal_review","reject"],"legal_review":["authority_review","reject"],"authority_review":["issuer_review","reject"],"issuer_review":["approve","reject","request_deficiency"],"approved":["issue"],"issued":["suspend","revoke"],"suspended":["reinstate","revoke"]}'::jsonb,'["authorized-issuer","legal-review","regulated-custodian-when-required"]'::jsonb,'{"legal_review_days":15,"authority_review_days":15}'::jsonb,'["unverified_underlying","unauthorized_issuer","custody_gap","settlement_gap","jurisdiction_block"]'::jsonb,'active','{"source":"omnii-tokenization-boundary","version":"1"}'::jsonb)
